sys_script.script:
(function executeRule(current, previous /*null when async*/) {

var sumAss=current.sum_assured;
if(current.case_status==2){
	current.assigned_to=getClosestSecondUW(sumAss);
	current.update()
}
else if(current.case_status==3){
	current.assigned_to=getClosestSeniorUW(sumAss);
	current.update()
}
else{

}

function getClosestSeniorUW(sumAssured) {
    var targetSum = sumAssured; // Default to 1,500,000 if not provided

    var gr = new GlideRecord('sys_user'); // Replace with your actual table name
    gr.addQuery('u_snr_uw', '>', targetSum); // Senior UW sum assured greater than target
    gr.orderBy('u_snr_uw'); // Closest higher value
    gr.query();

    if (gr.next()) {
        return gr.getValue('sys_id');
    }

}
function getClosestSecondUW(sumAssured) {
    var targetSum = sumAssured; // Default to 1,500,000 if not provided
    var closestUW = null;

    var gr = new GlideRecord('sys_user'); // Replace with your actual table name
    gr.addQuery('u_second_uw', '>', targetSum); // Senior UW sum assured greater than target
    gr.orderBy('u_second_uw'); // Closest higher value
    gr.query();

    if (gr.next()) {
        return gr.getValue('sys_id');
    }


}

})(current, previous);
